import { Stage } from "../Stage"

export default class extends Stage {
    protected *G(): Generator<void, void, unknown> {
        yield* this.wait(30)

        yield* this.text(`アオがいなくなってから、テントの中の声はいつも尖っていた。`)
        yield* this.text(`「だから言ったんだ。もっと早く、もっと大きく叩いておけばこんなことには……」`, { name: "TAMAMUSHIの男" })
        yield* this.text(`「お前の言う"大きく"のせいで、監視が増えたんだろうが。」`, { name: "テル" })
        yield* this.text(`「監視ぐらいで怯むなら、最初から名乗るんじゃない。」`, { name: "TAMAMUSHIの男" })

        yield* this.text(`二人とも、アオの死を悼んでいるはずだった。`)
        yield* this.text(`なのに、誰も同じ言葉を使っていなかった。`)

        yield* this.text(`「……もう、いいじゃん。」`, { name: "シオン" })
        yield* this.text(`「あんたは黙ってろ。看板は看板らしくしてろ。」`, { name: "TAMAMUSHIの男" })

        yield* this.text(`テルが何か言い返そうとしたが、少女の視線に気づいて止めた。`)
        yield* this.text(`「……なんでもない。」`, { name: "テル" })

        yield* this.text(`同じ場所にいて、同じものを失ったはずなのに、隣にいる人間が何を考えているのか、少女にはまるで分からなかった。`)
        yield* this.text(`分かり合えるはずだと、ずっと思っていたのに。`)
    }
}
